INSERT INTO dump_descriptions (base_key, description) VALUES ('nobunny', 'Removes the Easter Bunny’s cave and throwable props from the Great Egg Hunt.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('more_egg_swarms_p', 'Adds Egg Hunt swarms: 3 for 4 eggs, 4 for 6 eggs, and 5 for 8 eggs.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('mitbosshealthbar', 'Shows the smaller boss health bars above bosses while you look at them.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('instant_c4_indicator', 'Makes the C4 explosion-range indicator appear at full size immediately instead of expanding over a second.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('nomilestones', 'Prevents the assignment-progress popup on returning to the Space Rig from locking movement and chat.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noobjectthrowingsound', 'Removes the dwarf object-throwing sound.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('miracleteslamines_wip', 'Adds launcher-deployed Tesla Mines; three linked mines form a field that slows and damages enemies while draining charge.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
